global start, lat
probe kernel.function("vfs_read") { start[tid()] = gettimeofday_us() }
probe kernel.function("vfs_read").return {
  if (tid() in start) { lat[execname()] <<< gettimeofday_us() - start[tid()]; delete start[tid()] }
}
probe end {
  foreach (p in lat- limit 10) printf("%-16s avg=%dus max=%dus n=%d\n", p, @avg(lat[p]), @max(lat[p]), @count(lat[p]))
}

probe ioblock.request {
  if (bio_rw_num(rw) == BIO_WRITE)
    printf("%s %s %d bytes\n", execname(), devname, size)
}
# examples: /usr/share/systemtap/examples/io/iotop.stp, network/nettop.stp
